from pathlib import Path
import json,sys
P=Path(__file__).resolve().parent;R=P.parents[1]
b=json.loads((P/'JFp_SHA_INPUT.json').read_text())['message'];ls=lambda xs:'['+','.join(map(str,xs))+']'
out=[*(f'import JFp_SHABlock{i:02}' for i in range(25)),'import JFp_SHABlocks','set_option autoImplicit false','namespace AspisR1.JFp_SeedHash','open JFp_SHA256']
for i in range(25):out += [f'theorem len{i:02} : JFp_SHABlock{i:02}.input.length=64 := by rfl',f'#print axioms len{i:02}']
out += ['def head : List (List Nat) := ['+','.join(f'JFp_SHABlock{i:02}.input' for i in range(23))+']', 'def chunks : List (List Nat) := head ++ [JFp_SHABlock23.input,JFp_SHABlock24.input]',f'def tail : List Nat := {ls(b[1472:])}', 'def raw : List Nat := head.flatten ++ tail', 'theorem tailLength : tail.length=58 := by rfl','#print axioms tailLength','theorem headLength : head.flatten.length=1472 := by','  simp only [head,List.length_flatten,List.map_cons,List.map_nil,List.sum_cons,List.sum_nil,'+','.join(f'len{i:02}' for i in range(23))+']','  omega','#print axioms headLength','theorem rawLength : raw.length=1530 := by','  simp only [raw,List.length_append,headLength,tailLength]','#print axioms rawLength', 'theorem tailPad : tail ++ [128] ++ List.replicate 61 0 ++ [0,0,0,0,0,0,47,208] = JFp_SHABlock23.input ++ JFp_SHABlock24.input := by rfl','#print axioms tailPad','theorem padded : pad raw=chunks.flatten := by','  rw [pad,rawLength]','  change (head.flatten ++ tail) ++ [128] ++ List.replicate 61 0 ++ [0,0,0,0,0,0,47,208]=_','  simp only [List.append_assoc, chunks,List.flatten_append,List.flatten_cons,List.flatten_nil,List.append_nil]','  exact congrArg (fun t => head.flatten ++ t) (by simpa only [List.append_assoc] using tailPad)','#print axioms padded','theorem chunkLengths : ∀ c ∈ chunks,c.length=64 := by','  intro c hc','  simp only [chunks,head,List.mem_append,List.mem_cons,List.mem_singleton,List.not_mem_nil,or_false,or_assoc] at hc','  rcases hc with '+ '|'.join(f'h{i}' for i in range(25))]
for i in range(25):out+= [f'  · subst c;exact len{i:02}']
out += ['#print axioms chunkLengths','theorem paddedLength : (pad raw).length=1600 := by','  rw [padded]','  simp only [chunks,List.flatten_append,List.length_append,headLength,List.flatten_cons,List.flatten_nil,List.length_nil,len23,len24]','#print axioms paddedLength','theorem blockList : blocks ((pad raw).length/64) (pad raw)=chunks := by','  rw [paddedLength,padded]','  exact blocks_chunks chunks chunkLengths','#print axioms blockList','theorem checked : JFp_SHA256.hash raw=JFp_SHABlock24.result := by','  unfold JFp_SHA256.hash','  dsimp only','  rw [blockList]','  simp only [chunks,head,List.foldl_append,List.foldl_cons,List.foldl_nil]']
for i in range(25):out += [f'  rw [show '+('initial' if i==0 else f'JFp_SHABlock{i-1:02}.result')+f'=JFp_SHABlock{i:02}.start from rfl,JFp_SHABlock{i:02}.checked]']
out += ['#print axioms checked','end AspisR1.JFp_SeedHash']
s='\n'.join(out)+'\n';p=R/'lean/JFp_SeedHash.lean'
if '--check' in sys.argv:assert p.read_text()==s
else:p.write_text(s)
